/** TUFF BEATZ Studio OS V16.2 — Production Verification, lifecycle evidence matrix + anomaly detection (read-only) */
function tuff_beatz_v16_verification_checks($id=0){$checks=array();$add=function($key,$label,$ok,$detail='')use(&$checks){$checks[]=array('key'=>$key,'label'=>$label,'status'=>$ok?'pass':'fail','detail'=>$detail?:($ok?'PASS':'FAIL'));};$required=array('vault'=>'tuff_beatz_vault_files','authorization'=>'tuff_beatz_auth_can','runtime'=>'tuff_beatz_runtime_health','integrity'=>'tuff_beatz_integrity_report','release-readiness'=>'tuff_beatz_rc_checks','delivery-manifest'=>'tuff_beatz_delivery_manifest','delivery-history'=>'tuff_beatz_delivery_manifest_history','acceptance-history'=>'tuff_beatz_delivery_acceptance_history','final-evidence'=>'tuff_beatz_has_final_delivery_evidence');foreach($required as $key=>$fn)$add('module-'.$key,ucwords(str_replace('-',' ',$key)).' module',function_exists($fn),function_exists($fn)?'Loaded':'Missing '.$fn);$theme=get_template_directory();foreach(array('inc/private-file-vault.php','inc/canonical-asset-bridge.php','inc/file-manager-asset-sync.php','inc/final-delivery-guard.php','inc/delivery-engine.php','inc/permission-hardening.php','inc/data-integrity.php','inc/runtime-health.php','inc/release-candidate.php') as $file)$add('file-'.$file,'Required file: '.$file,is_readable($theme.'/'.$file),is_readable($theme.'/'.$file)?'Readable':'Missing or unreadable');if($id&&get_post_type($id)==='tb_request'){$can_view=function_exists('tuff_beatz_user_can_view_request')&&tuff_beatz_user_can_view_request($id);$add('project-view','Current user project access',$can_view,$can_view?'Authorized':'Not authorized for this project');if($can_view){$runtime=tuff_beatz_runtime_health($id);$add('runtime-state','Runtime Health has no critical failures',empty($runtime['critical']),'Critical: '.(int)($runtime['critical']??0).' / Warnings: '.(int)($runtime['warnings']??0));$integrity=tuff_beatz_integrity_report($id);$blocking=0;foreach((array)($integrity['issues']??array()) as $issue)if(in_array($issue['severity']??'',array('critical','high'),true))$blocking++;$add('integrity-state','No high/critical integrity conflicts',$blocking===0,$blocking.' blocking integrity issue(s)');$rc=tuff_beatz_rc_checks($id,'state');$add('release-state','Release readiness is not blocked',($rc['status']??'blocked')!=='blocked','RC status: '.($rc['status']??'unknown'));$status=(string)(get_post_meta($id,'_tb_request_status',true)?:'new');if(in_array($status,array('delivery','completed'),true)){$manifest=tuff_beatz_delivery_manifest($id);$history=tuff_beatz_delivery_manifest_history($id);$latest=$history?end($history):array();$manifest_ok=!empty($manifest['manifest_id'])&&!empty($latest['manifest_id'])&&hash_equals((string)$manifest['manifest_id'],(string)$latest['manifest_id'])&&(int)($manifest['release_version']??0)===(int)($latest['release_version']??0);$add('manifest-history','Current manifest matches latest release-history entry',$manifest_ok,$manifest_ok?'Exact manifest/version match':'Manifest/history mismatch');$final=tuff_beatz_has_final_delivery_evidence($id);$add('final-evidence','Active canonical Final evidence',$final,$final?'Present':'Missing');}if($status==='completed'){$accept=function_exists('tuff_beatz_delivery_acceptance_record')?tuff_beatz_delivery_acceptance_record($id):array();$manifest=tuff_beatz_delivery_manifest($id);$accept_ok=!empty($accept['acceptance_id'])&&!empty($accept['manifest_id'])&&!empty($manifest['manifest_id'])&&hash_equals((string)$accept['manifest_id'],(string)$manifest['manifest_id'])&&(int)($accept['release_version']??0)===(int)($manifest['release_version']??0);$add('acceptance-binding','Completed project acceptance matches exact release',$accept_ok,$accept_ok?'Acceptance ID and release binding verified':'Acceptance/release binding incomplete');}}}$failed=0;foreach($checks as $check)if($check['status']==='fail')$failed++;return array('version'=>'16.2','mode'=>'read-only','status'=>$failed?'attention':'verified','failed'=>$failed,'passed'=>count($checks)-$failed,'checks'=>$checks,'checked_at'=>current_time('mysql'));}
function tuff_beatz_v162_project_evidence($id){$status=(string)(get_post_meta($id,'_tb_request_status',true)?:'new');$order=function_exists('tuff_beatz_workflow_order')?tuff_beatz_workflow_order():array('new','reviewing','approved','in-progress','revision','mastering','delivery','completed');$index=array_search($status,$order,true);if($index===false)$index=0;$files=function_exists('tuff_beatz_vault_files')?tuff_beatz_vault_files($id):array();$types=array();$active=array();foreach($files as $f){if(!empty($f['archived']))continue;$t=function_exists('tuff_beatz_vault_asset_type')?tuff_beatz_vault_asset_type($f):sanitize_key($f['asset_type']??'');if($t)$types[]=$t;$active[]=$f;}$types=array_values(array_unique($types));$manifest=function_exists('tuff_beatz_delivery_manifest')?tuff_beatz_delivery_manifest($id):array();$history=function_exists('tuff_beatz_delivery_manifest_history')?tuff_beatz_delivery_manifest_history($id):array();$accept=function_exists('tuff_beatz_delivery_acceptance_record')?tuff_beatz_delivery_acceptance_record($id):array();return array('status'=>$status,'index'=>$index,'types'=>$types,'files'=>$active,'approved'=>(string)get_post_meta($id,'_tb_approved_mix_file',true),'manifest'=>$manifest,'history'=>$history,'accept'=>$accept);}
function tuff_beatz_v161_lifecycle_scenarios($id){$e=tuff_beatz_v162_project_evidence($id);$defs=array(array('key'=>'intake','label'=>'Intake','required'=>0,'evidence'=>true,'detail'=>'Project record exists'),array('key'=>'production','label'=>'Production','required'=>3,'evidence'=>array_intersect($e['types'],array('source','stem')),'detail'=>'Source/stem evidence'),array('key'=>'mix-review','label'=>'Mix Review','required'=>4,'evidence'=>in_array('mix',$e['types'],true),'detail'=>'Canonical mix evidence'),array('key'=>'mix-approval','label'=>'Mix Approval','required'=>5,'evidence'=>!empty($e['approved']),'detail'=>'Approved mix recorded'),array('key'=>'mastering','label'=>'Mastering','required'=>5,'evidence'=>in_array('master',$e['types'],true)||in_array('final',$e['types'],true),'detail'=>'Master/final evidence'),array('key'=>'final','label'=>'Final','required'=>6,'evidence'=>in_array('final',$e['types'],true),'detail'=>'Canonical Final evidence'),array('key'=>'delivery','label'=>'Delivery','required'=>6,'evidence'=>!empty($e['manifest']['manifest_id']),'detail'=>'Official release manifest'),array('key'=>'acceptance','label'=>'Acceptance','required'=>7,'evidence'=>!empty($e['accept']['acceptance_id']),'detail'=>'Exact client acceptance record'));$out=array();foreach($defs as $d){$reached=$e['index']>=$d['required'];$state=!$reached?'pending':((bool)$d['evidence']?'verified':'attention');$out[]=array('key'=>$d['key'],'label'=>$d['label'],'state'=>$state,'detail'=>$d['detail']);}return $out;}
function tuff_beatz_v162_anomalies($id){$e=tuff_beatz_v162_project_evidence($id);$a=array();$push=function($key,$severity,$label,$detail)use(&$a){$a[]=array('key'=>$key,'severity'=>$severity,'label'=>$label,'detail'=>$detail);};if($e['index']>=3&&!array_intersect($e['types'],array('source','stem')))$push('production-without-source','high','Production without source evidence','Workflow reached Production or later but no active canonical source/stem exists.');if($e['index']>=4&&!in_array('mix',$e['types'],true))$push('review-without-mix','high','Mix Review without canonical mix','Workflow reached Mix Review or later but no active canonical mix exists.');if($e['index']>=5&&empty($e['approved']))$push('mastering-without-approval','high','Mastering without mix approval','Workflow reached Mastering or later without an approved mix record.');if($e['index']>=6&&!in_array('final',$e['types'],true))$push('delivery-without-final','critical','Delivery without canonical Final','Delivery/completed state exists without active canonical Final evidence.');if(!empty($e['manifest']['manifest_id'])&&!in_array('final',$e['types'],true))$push('manifest-without-final','critical','Release manifest without active Final','A release manifest exists while active canonical Final evidence is absent.');if(!empty($e['accept']['acceptance_id'])&&empty($e['manifest']['manifest_id']))$push('acceptance-without-manifest','critical','Acceptance without release manifest','Acceptance identity exists without a current official release manifest.');if(!empty($e['accept']['acceptance_id'])&&!empty($e['manifest']['manifest_id'])&&((string)($e['accept']['manifest_id']??'')!==(string)$e['manifest']['manifest_id']||(int)($e['accept']['release_version']??0)!==(int)($e['manifest']['release_version']??0)))$push('acceptance-release-mismatch','critical','Acceptance bound to different release','Current acceptance does not match the exact current manifest ID/version.');if(!empty($e['manifest']['manifest_id'])){$latest=$e['history']?end($e['history']):array();if(empty($latest['manifest_id'])||(string)$latest['manifest_id']!==(string)$e['manifest']['manifest_id']||(int)($latest['release_version']??0)!==(int)($e['manifest']['release_version']??0))$push('manifest-history-mismatch','high','Current release/history mismatch','Current release manifest does not match the latest append-preserving history entry.');foreach((array)($e['manifest']['files']??array()) as $f)if(($f['asset_type']??'')!=='final'){$push('manifest-non-final','critical','Non-Final asset in release manifest','Release manifest contains an asset that is not canonical Final.');break;}}if($e['status']==='completed'&&empty($e['accept']['acceptance_id']))$push('completed-without-acceptance','critical','Completed without acceptance identity','Project is completed without a canonical client acceptance ID.');return $a;}
function tuff_beatz_v16_verification_workspace(){if(!is_page('project-dashboard')||!is_user_logged_in())return;$id=(int)($_GET['project']??0);if(!$id)return;$producer=function_exists('tuff_beatz_auth_is_producer')?tuff_beatz_auth_is_producer($id):current_user_can('edit_post',$id);if(!$producer)return;$report=tuff_beatz_v16_verification_checks($id);$scenarios=tuff_beatz_v161_lifecycle_scenarios($id);$anomalies=tuff_beatz_v162_anomalies($id);?><script>document.addEventListener('DOMContentLoaded',function(){var root=document.querySelector('.tb-project-dashboard')||document.querySelector('main');if(!root)return;var panel=document.createElement('section');panel.className='tb-v16-verification';panel.innerHTML=<?php ob_start();?><div class="tb-v16-head"><div><small>STUDIO OS V16.2 • READ-ONLY</small><strong>Production Verification</strong></div><span><?php echo esc_html($anomalies?'ATTENTION':strtoupper($report['status']));?></span></div><div class="tb-v16-counts"><b><?php echo esc_html((string)$report['passed']);?></b><span>PASS</span><b><?php echo esc_html((string)$report['failed']);?></b><span>CHECK FAIL</span><b><?php echo esc_html((string)count($anomalies));?></b><span>ANOMALIES</span></div><div class="tb-v16-scenarios"><?php foreach($scenarios as $s):?><div class="is-<?php echo esc_attr($s['state']);?>"><i></i><p><strong><?php echo esc_html($s['label']);?></strong><span><?php echo esc_html($s['detail']);?></span></p><b><?php echo esc_html(strtoupper($s['state']));?></b></div><?php endforeach;?></div><?php if($anomalies):?><div class="tb-v16-anomalies"><small>EVIDENCE CONSISTENCY MATRIX</small><?php foreach($anomalies as $a):?><div class="is-<?php echo esc_attr($a['severity']);?>"><b><?php echo esc_html(strtoupper($a['severity']));?></b><p><strong><?php echo esc_html($a['label']);?></strong><span><?php echo esc_html($a['detail']);?></span></p></div><?php endforeach;?></div><?php endif;?><?php if($report['failed']):?><div class="tb-v16-failures"><?php foreach($report['checks'] as $check)if($check['status']==='fail'):?><div><b>CHECK</b><p><strong><?php echo esc_html($check['label']);?></strong><span><?php echo esc_html($check['detail']);?></span></p></div><?php endif;?></div><?php endif;?><p class="tb-v16-note">V16.2 detects inconsistent production evidence. It is observational only: no workflow advancement, metadata repair, deletion, release creation, or acceptance mutation occurs automatically.</p><?php $html=ob_get_clean();echo wp_json_encode($html);?>;root.insertBefore(panel,root.firstChild);});</script><?php }
